\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows} %% Can be useful, not essential
\usetikzlibrary{intersections} %% Can be useful, not essential
\usepgfplotslibrary{fillbetween} %% Can be useful, not essential
\begin{document}
\pagestyle{empty} 

\begin{tikzpicture}[scale=1]

\begin{scope}
\draw[thick, ->] (-2.5,0)--(2.5,0) node[pos=0.5, sloped, below=2pt]{${x_0}$}
node[black, right] {$x$};	
\draw[blue, line width=2.0pt] (-2,0)--(2,0)
node[black, above, xshift=-0.9cm] {$\delta$}
node[black, above left, xshift=-2.7cm] {$\delta$};
\draw[black, draw=none,fill=black] (0,0) circle (1.8pt);
\draw[color=blue, circle, thick, fill=white] (-2,0) circle (3.5pt);
\draw[color=blue, circle, thick, fill=white] (2,0) circle (3.5pt);
\end{scope}

\end{tikzpicture}
\end{document}

